import { Component, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { SheetService } from '../../core/sheet.service';
import { People } from '../people/people';
import { Rates } from '../rates/rates';
import { SheetToday } from './sheet-today';

// Choose the active sheet by typing its id and loading it.
@Component({
  selector: 'app-sheet-picker',
  imports: [ReactiveFormsModule, SheetToday, Rates, People],
  template: `
    <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Load sheet">
      <label for="sheet-id-input">Sheet id</label>
      <input id="sheet-id-input" data-testid="sheet-id-input" formControlName="id" />
      <button type="submit" data-testid="sheet-load">Load</button>
      @if (error()) {
        <p role="alert" data-testid="sheet-error">{{ error() }}</p>
      }
    </form>
    @if (sheets.sheetId(); as current) {
      <p>Sheet: <span data-testid="sheet-current-id">{{ current }}</span></p>
      <app-sheet-today />
      <app-rates />
      <app-people />
    }
  `,
})
export class SheetPicker {
  protected readonly sheets = inject(SheetService);
  protected readonly form = new FormGroup({ id: new FormControl('', { nonNullable: true }) });
  protected readonly error = signal('');

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
  }

  protected submit(): void {
    this.error.set('');
    const id = this.form.controls.id.value.trim();
    if (!/^[A-Za-z0-9_-]{1,100}$/.test(id)) {
      this.error.set('Enter a sheet id (letters, digits, - or _).');
      return;
    }
    this.sheets.load(id).subscribe({ error: () => this.error.set('Could not load that sheet.') });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';
import { SessionService } from './session.service';
import { SheetService } from './sheet.service';

export type Grade = 'A' | 'B' | 'C';

export const GRADES: readonly Grade[] = ['A', 'B', 'C'];

export interface Person {
  id: number;
  name: string;
  grade: Grade;
}

export interface PersonForm {
  name: string;
  grade: Grade;
}

// The active sheet's people, in the order they were added.
@Injectable({ providedIn: 'root' })
export class PeopleService {
  private readonly http = inject(HttpClient);
  private readonly session = inject(SessionService);
  private readonly sheets = inject(SheetService);
  private readonly list = signal<Person[]>([]);

  readonly people = this.list.asReadonly();

  reload(): void {
    const id = this.sheets.sheetId();
    if (!id) {
      this.list.set([]);
      return;
    }
    this.http
      .get<Person[]>(this.url(id), { headers: this.session.headers() })
      .subscribe((people) => {
        if (this.sheets.sheetId() === id) this.list.set(people);
      });
  }

  add(form: PersonForm): Observable<Person> {
    return this.http
      .post<Person>(this.url(this.sheet()), form, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => [...all, p])));
  }

  edit(personId: number, form: PersonForm): Observable<Person> {
    return this.http
      .put<Person>(`${this.url(this.sheet())}/${personId}`, form, { headers: this.session.headers() })
      .pipe(tap((p) => this.list.update((all) => all.map((o) => (o.id === p.id ? p : o)))));
  }

  private sheet(): string {
    const id = this.sheets.sheetId();
    if (!id) throw new Error('no sheet loaded');
    return id;
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/people`;
  }
}
